    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer in = new StreamTokenizer(br);
        in.resetSyntax();
        in.wordChars(33, 255);
        in.whitespaceChars(0, 32);
        in.nextToken();
        int n = Integer.parseInt(in.sval);
        String[][] instructions = new String[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); instructions[i][0] = in.sval;
            in.nextToken(); instructions[i][1] = in.sval;
        }
        in.nextToken();
        int t = Integer.parseInt(in.sval);
        String[] treasure = new String[t];
        for (int i = 0; i < t; i++) { in.nextToken(); treasure[i] = in.sval; }
        List<String> res = filterRooms(instructions, treasure);
        if (res.isEmpty()) { System.out.println(-1); return; }
        System.out.println(String.join(" ", res));
